package com.sky.handler;

import static org.junit.jupiter.api.Assertions.*;

import com.sky.result.Result;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：当发生NumberFormatException时，应返回正确的错误结果")
    void testExceptionHandler_NumberFormatException_ReturnsCorrectErrorResult() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("For input string: \"abc\"");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        // 验证返回的错误消息为固定的"请求参数格式错误"
        assertEquals("请求参数格式错误", result.getData());
        // 验证结果码不是成功码1（假设错误码非1）
        assertNotEquals(1, result.getCode());
    }

    @Test
    @DisplayName("边界测试：验证修复后NumberFormatException被正确处理而不抛出异常")
    void testExceptionHandler_NumberFormatException_DoesNotThrowException() {
        // Arrange - 模拟原始导致异常的输入
        NumberFormatException exception = new NumberFormatException("For input string: \"xyz\"");

        // Act & Assert - 确保方法调用不会抛出异常
        assertDoesNotThrow(() -> {
            Result<String> result = globalExceptionHandler.exceptionHandler(exception);
            assertNotNull(result);
            assertEquals("请求参数格式错误", result.getData());
        });
    }

    @Test
    @DisplayName("正向测试：验证NumberFormatException处理器被正确触发")
    void testExceptionHandler_NumberFormatException_HandlerTriggered() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("Invalid number format");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        // 验证结果码表示错误（非1）
        assertTrue(result.getCode() != 1, "Error code should not be success code 1");
        // 验证返回的错误消息包含固定文本
        assertEquals("请求参数格式错误", result.getData());
    }

    @Test
    @DisplayName("正向测试：验证其他异常处理器未受影响 - MissingPathVariableException")
    void testExceptionHandler_MissingPathVariableException_StillWorks() {
        // Arrange - 创建一个MissingPathVariableException实例，但需要模拟或使用构造函数
        // 由于MissingPathVariableException需要参数，使用简单构造
        // 假设MissingPathVariableException有一个公开构造函数，从Spring文档看，它有。
        // 为了简单，使用反射或直接构造，但这里使用一个简单的异常消息
        // 注意：必须确保异常类在项目中可用
        org.springframework.web.bind.MissingPathVariableException exception = 
            new org.springframework.web.bind.MissingPathVariableException("pathVar", null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals("请求参数绑定失败", result.getData());
    }
}
